#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <hls_math.h>

// ---------------------------------------------------------------
// Type definitions derived from params.yaml
// bits_per_component = bits + signed
// ap_fixed<bits_per_component, bits_per_component - fraction>
// ---------------------------------------------------------------

// acm / A matrix  : bits=22, signed=1, fraction=0  → ap_fixed<23,23>
typedef ap_fixed<23, 23> acm_t;

// max_iter        : bits=8,  signed=0, fraction=0  → ap_uint<8>
typedef ap_uint<8> max_iter_t;

// eigenvalues     : bits=22, signed=1, fraction=0  → ap_fixed<23,23>
typedef ap_fixed<23, 23> eigval_t;

// eigenvectors    : bits=22, signed=1, fraction=20 → ap_fixed<23,3>
typedef ap_fixed<23, 3> eigvec_t;

// ite             : bits=8,  signed=0, fraction=0  → ap_uint<8>
typedef ap_uint<8> ite_t;

// Matrix / vector dimensions
static const int N = 10;

// Complex pair structs
struct acm_cplx   { acm_t   re; acm_t   im; };
struct eigval_cplx{ eigval_t re; eigval_t im; };
struct eigvec_cplx{ eigvec_t re; eigvec_t im; };

// ---------------------------------------------------------------
// Top-level function declaration
// ---------------------------------------------------------------
void kernel_top(
    acm_cplx    A_in[N][N],
    max_iter_t  max_iter,
    eigval_cplx eigenvalues[N],
    eigvec_cplx eigenvectors[N][N],
    ite_t       &ite
);

#endif // KERNEL_H

