#include "kernel.h"
#include <hls_math.h>

// Internal floating-point precision for trigonometric / iterative work
typedef double flt_t;

static flt_t flt_abs(flt_t x) { return (x < 0) ? -x : x; }
static flt_t flt_sqrt(flt_t x) { return hls::sqrt(x); }
static flt_t flt_atan(flt_t x) { return hls::atan(x); }
static flt_t flt_atan2(flt_t y, flt_t x) { return hls::atan2(y, x); }
static flt_t flt_cos(flt_t x)  { return hls::cos(x); }
static flt_t flt_sin(flt_t x)  { return hls::sin(x); }

// Small epsilon for convergence check (matches Python 1e-8)
static const flt_t EPS = 1e-8;

// ---------------------------------------------------------------
// kernel_top
// ---------------------------------------------------------------
void kernel_top(
    acm_cplx    A_in[N][N],
    max_iter_t  max_iter,
    eigval_cplx eigenvalues[N],
    eigvec_cplx eigenvectors[N][N],
    ite_t       &ite
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INTERFACE ap_none    port=max_iter
#pragma HLS INTERFACE ap_none    port=ite
#pragma HLS ARRAY_PARTITION variable=A_in       complete dim=0
#pragma HLS ARRAY_PARTITION variable=eigenvalues complete dim=1
#pragma HLS ARRAY_PARTITION variable=eigenvectors complete dim=0

    // ---- Copy input A into working double array ----
    flt_t A_re[N][N];
    flt_t A_im[N][N];
    INIT_A_ROW:
    for (int i = 0; i < N; i++) {
        INIT_A_COL:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            A_re[i][j] = (flt_t)A_in[i][j].re;
            A_im[i][j] = (flt_t)A_in[i][j].im;
        }
    }

    // ---- Identity matrix V ----
    flt_t V_re[N][N];
    flt_t V_im[N][N];
    INIT_V_ROW:
    for (int i = 0; i < N; i++) {
        INIT_V_COL:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            V_re[i][j] = (i == j) ? (flt_t)1.0 : (flt_t)0.0;
            V_im[i][j] = (flt_t)0.0;
        }
    }

    int last_z = 0;
    int mi = (int)max_iter;

    // ---- Main Jacobi loop ----
    JACOBI_OUTER:
    for (int z = 0; z < 256; z++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=255
        if (z >= mi) break;

        // --- Find pivot (p, q) with max |A[i,j]| for i<j ---
        flt_t off_diag_max = (flt_t)0.0;
        int p = 0, q = 1;
        PIVOT_I:
        for (int i = 0; i < N; i++) {
            PIVOT_J:
            for (int j = i + 1; j < N; j++) {
#pragma HLS PIPELINE II=1
                flt_t mag = flt_sqrt(A_re[i][j]*A_re[i][j] + A_im[i][j]*A_im[i][j]);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        if (off_diag_max < EPS) {
            last_z = z;
            break;
        }
        last_z = z;

        // --- Compute rotation parameters ---
        flt_t a_pp_re = A_re[p][p];
        flt_t a_qq_re = A_re[q][q];
        flt_t a_pq_re = A_re[p][q];
        flt_t a_pq_im = A_im[p][q];

        flt_t a_pq_abs = flt_sqrt(a_pq_re*a_pq_re + a_pq_im*a_pq_im);
        flt_t denom    = a_pp_re - a_qq_re;

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        flt_t theta;
        if (flt_abs(denom) < EPS) {
            theta = (flt_t)0.7853981633974483; // pi/4
        } else {
            theta = (flt_t)0.5 * flt_atan((flt_t)2.0 * a_pq_abs / denom);
        }

        // phi = -angle(a_pq)
        flt_t phi = -flt_atan2(a_pq_im, a_pq_re);

        flt_t cos_t  = flt_cos(theta);
        flt_t sin_t  = flt_sin(theta);
        flt_t cos_ph = flt_cos(phi);
        flt_t sin_ph = flt_sin(phi);

        // U[p,p] =  cos(theta)
        // U[p,q] =  sin(theta)*exp(-j*phi) =  sin_t*(cos_ph - j*sin_ph)
        // U[q,p] =  sin(theta)*exp(+j*phi) =  sin_t*(cos_ph + j*sin_ph)
        // U[q,q] = -cos(theta)
        flt_t Upp_re =  cos_t;
        flt_t Upq_re =  sin_t * cos_ph;
        flt_t Upq_im = -sin_t * sin_ph;
        flt_t Uqp_re =  sin_t * cos_ph;
        flt_t Uqp_im =  sin_t * sin_ph;
        flt_t Uqq_re = -cos_t;

        // ---- A_new = U^H * A * U ----
        // Step 1: tmp = A * U  (only columns p and q change)
        flt_t tmp_re[N][N];
        flt_t tmp_im[N][N];
        TMP_COPY_ROW:
        for (int i = 0; i < N; i++) {
            TMP_COPY_COL:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                tmp_re[i][j] = A_re[i][j];
                tmp_im[i][j] = A_im[i][j];
            }
        }
        // column p: A*U[:,p]
        AXUP_COL_P:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            flt_t r = A_re[i][p]*Upp_re - A_im[i][p]*(flt_t)0.0
                    + A_re[i][q]*Uqp_re - A_im[i][q]*Uqp_im;
            flt_t im= A_im[i][p]*Upp_re + A_re[i][p]*(flt_t)0.0
                    + A_im[i][q]*Uqp_re + A_re[i][q]*Uqp_im;
            tmp_re[i][p] = r;
            tmp_im[i][p] = im;
        }
        // column q: A*U[:,q]
        AXUP_COL_Q:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            flt_t r = A_re[i][p]*Upq_re - A_im[i][p]*Upq_im
                    + A_re[i][q]*Uqq_re - A_im[i][q]*(flt_t)0.0;
            flt_t im= A_im[i][p]*Upq_re + A_re[i][p]*Upq_im
                    + A_im[i][q]*Uqq_re + A_re[i][q]*(flt_t)0.0;
            tmp_re[i][q] = r;
            tmp_im[i][q] = im;
        }

        // Step 2: A_new = U^H * tmp  (only rows p and q change)
        flt_t An_re[N][N];
        flt_t An_im[N][N];
        ACOPY_ROW:
        for (int i = 0; i < N; i++) {
            ACOPY_COL:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                An_re[i][j] = tmp_re[i][j];
                An_im[i][j] = tmp_im[i][j];
            }
        }
        // row p: U[:,p]^H * tmp = conj(U[p,p])*tmp[p,j] + conj(U[q,p])*tmp[q,j]
        // conj(U[p,p])=Upp_re (real), conj(U[q,p])=Uqp_re - j*Uqp_im
        UHXT_ROW_P:
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            flt_t r = Upp_re*tmp_re[p][j] - (flt_t)0.0*tmp_im[p][j]
                    + Uqp_re*tmp_re[q][j] + Uqp_im*tmp_im[q][j]; // conj(Uqp)
            flt_t im= Upp_re*tmp_im[p][j] + (flt_t)0.0*tmp_re[p][j]
                    + Uqp_re*tmp_im[q][j] - Uqp_im*tmp_re[q][j];
            An_re[p][j] = r;
            An_im[p][j] = im;
        }
        // row q: conj(U[p,q])*tmp[p,j] + conj(U[q,q])*tmp[q,j]
        // conj(U[p,q])=Upq_re+j*Upq_im (negate imag), conj(U[q,q])=Uqq_re (real)
        UHXT_ROW_Q:
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            flt_t r = Upq_re*tmp_re[p][j] + Upq_im*tmp_im[p][j]
                    + Uqq_re*tmp_re[q][j] - (flt_t)0.0*tmp_im[q][j];
            flt_t im= Upq_re*tmp_im[p][j] - Upq_im*tmp_re[p][j]
                    + Uqq_re*tmp_im[q][j] + (flt_t)0.0*tmp_re[q][j];
            An_re[q][j] = r;
            An_im[q][j] = im;
        }

        // Zero out pivot (enforce exact symmetry)
        An_re[p][q] = (flt_t)0.0; An_im[p][q] = (flt_t)0.0;
        An_re[q][p] = (flt_t)0.0; An_im[q][p] = (flt_t)0.0;

        // Copy back
        UPDATE_A_ROW:
        for (int i = 0; i < N; i++) {
            UPDATE_A_COL:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                A_re[i][j] = An_re[i][j];
                A_im[i][j] = An_im[i][j];
            }
        }

        // ---- V_new = V * U ----
        // Only columns p and q of V change
        flt_t Vp_re[N], Vp_im[N];
        flt_t Vq_re[N], Vq_im[N];
        V_UPDATE:
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            // new col p = V[:,p]*U[p,p] + V[:,q]*U[q,p]
            Vp_re[i] = V_re[i][p]*Upp_re - V_im[i][p]*(flt_t)0.0
                     + V_re[i][q]*Uqp_re - V_im[i][q]*Uqp_im;
            Vp_im[i] = V_im[i][p]*Upp_re + V_re[i][p]*(flt_t)0.0
                     + V_im[i][q]*Uqp_re + V_re[i][q]*Uqp_im;
            // new col q = V[:,p]*U[p,q] + V[:,q]*U[q,q]
            Vq_re[i] = V_re[i][p]*Upq_re - V_im[i][p]*Upq_im
                     + V_re[i][q]*Uqq_re - V_im[i][q]*(flt_t)0.0;
            Vq_im[i] = V_im[i][p]*Upq_re + V_re[i][p]*Upq_im
                     + V_im[i][q]*Uqq_re + V_re[i][q]*(flt_t)0.0;
        }
        V_WRITE_BACK:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            V_re[i][p] = Vp_re[i]; V_im[i][p] = Vp_im[i];
            V_re[i][q] = Vq_re[i]; V_im[i][q] = Vq_im[i];
        }
    }

    // ---- Pack outputs ----
    PACK_EVALS:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        eigenvalues[i].re = (eigval_t)A_re[i][i];
        eigenvalues[i].im = (eigval_t)A_im[i][i];
    }
    PACK_EVEC_ROW:
    for (int i = 0; i < N; i++) {
        PACK_EVEC_COL:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            eigenvectors[i][j].re = (eigvec_t)V_re[i][j];
            eigenvectors[i][j].im = (eigvec_t)V_im[i][j];
        }
    }
    ite = (ite_t)last_z;
}

