#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include "kernel.h"

// ---------------------------------------------------------------
// Path constants (exact, no runtime construction)
// ---------------------------------------------------------------
static const char IO_DIR[]  = "/home/mbenton/verilog_rapid_prototyping/conversion_013/eig_10_io/";
static const char SIM_DIR[] = "/home/mbenton/verilog_rapid_prototyping/conversion_013/build/sim/";

// ---------------------------------------------------------------
// Helper: open a file or abort
// ---------------------------------------------------------------
static FILE* xfopen(const char* dir, const char* name, const char* mode)
{
    char path[512];
    snprintf(path, sizeof(path), "%s%s", dir, name);
    FILE* f = fopen(path, mode);
    if (!f) {
        fprintf(stderr, "Cannot open file: %s\n", path);
        exit(1);
    }
    return f;
}

// ---------------------------------------------------------------
// Read utilities
// ---------------------------------------------------------------
static void read_complex_mat(FILE* f, int rows, int cols,
                              double re[][10], double im[][10])
{
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            double r = 0.0, im_ = 0.0;
            if (fscanf(f, "%lf %lf", &r, &im_) != 2) {
                fprintf(stderr, "Parse error reading complex matrix\n");
                exit(1);
            }
            re[i][j] = r;
            im[i][j] = im_;
        }
    }
}

int main()
{
    // ---------------------------------------------------------------
    // 1. Read input A (call index 0 only: first 10×10 block)
    // ---------------------------------------------------------------
    FILE* fA = xfopen(IO_DIR, "in_A.txt", "r");

    // Each call has N*N=100 complex scalars; skip nothing (index 0)
    double A_re[N][N], A_im[N][N];
    read_complex_mat(fA, N, N, A_re, A_im);
    fclose(fA);

    // ---------------------------------------------------------------
    // 2. Read max_iter (call index 0)
    // ---------------------------------------------------------------
    FILE* fmi = xfopen(IO_DIR, "in_max_iter.txt", "r");
    int max_iter_val = 0;
    if (fscanf(fmi, "%d", &max_iter_val) != 1) {
        fprintf(stderr, "Parse error reading max_iter\n");
        exit(1);
    }
    fclose(fmi);

    // ---------------------------------------------------------------
    // 3. Pack inputs into HLS types
    // ---------------------------------------------------------------
    acm_cplx   A_hls[N][N];
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            A_hls[i][j].re = (acm_t)A_re[i][j];
            A_hls[i][j].im = (acm_t)A_im[i][j];
        }

    max_iter_t mi_hls = (max_iter_t)(unsigned)max_iter_val;

    // ---------------------------------------------------------------
    // 4. Call kernel
    // ---------------------------------------------------------------
    eigval_cplx eigenvalues[N];
    eigvec_cplx eigenvectors[N][N];
    ite_t       ite_out;

    kernel_top(A_hls, mi_hls, eigenvalues, eigenvectors, ite_out);

    // ---------------------------------------------------------------
    // 5. Write outputs
    // ---------------------------------------------------------------

    // out_0.txt  — eigenvalues (N complex scalars)
    {
        FILE* fo = xfopen(SIM_DIR, "out_0.txt", "w");
        for (int i = 0; i < N; i++) {
            fprintf(fo, "%.17g %.17g\n",
                    (double)eigenvalues[i].re,
                    (double)eigenvalues[i].im);
        }
        fclose(fo);
    }

    // out_1.txt  — eigenvectors (N×N complex matrix)
    {
        FILE* fo = xfopen(SIM_DIR, "out_1.txt", "w");
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++) {
                fprintf(fo, "%.17g %.17g\n",
                        (double)eigenvectors[i][j].re,
                        (double)eigenvectors[i][j].im);
            }
        fclose(fo);
    }

    // out_2.txt  — ite (scalar integer)
    {
        FILE* fo = xfopen(SIM_DIR, "out_2.txt", "w");
        fprintf(fo, "%u\n", (unsigned)ite_out);
        fclose(fo);
    }

    printf("Simulation complete.\n");
    printf("  eigenvalues  -> %sout_0.txt\n", SIM_DIR);
    printf("  eigenvectors -> %sout_1.txt\n", SIM_DIR);
    printf("  ite          -> %sout_2.txt\n", SIM_DIR);
    return 0;
}
